base.src/user.ts:
export interface User {
  active: boolean;
  admin: boolean;
}

files.src/active.ts:
import type { User } from "./user";
export function label(user: User) {
  if (!user.active) return "inactive";
  else return "active";
}

files.src/admin.ts:
import type { User } from "./user";
export function role(user: User) {
  if (user.admin) return "admin";
  else return "member";
}

files.src/badge.ts:
import type { User } from "./user";
export function badge(user: User) {
  if (user.admin && user.active) return "gold";
  else return "none";
}
